  nc = `Eventi a tema: %1$s`,
  rc = `Halloween 2022`,
  ic = `Questo evento riguarda gli aggiornamenti del tuo gioco per Halloween 2022? Se stai aggiungendo nuove mappe, skin, immagini o altri contenuti al tuo gioco per Halloween o gestisci eventi a tempo limitato con contenuti speciali, sfide o altre attività simili, ci piacerebbe saperlo. Stiamo valutando modi migliori per far conoscere meglio gli eventi a tema a un pubblico più vasto, ma prima abbiamo bisogno di un'idea migliore del tipo di attività che gli sviluppatori ospitano nei tuoi giochi (se presenti) per celebrare le feste. Fai clic qui sotto su "Attiva" se questo evento riguarda un aggiornamento del tuo gioco per Halloween 2022.`,
  ac = `Eventi a tema Halloween`,
  oc = `Stai organizzando un evento o stai aggiungendo contenuti a tema Halloween? Consulta la %1$s per saperne di più sulla partecipazione a "Steam Scream" con il tuo evento nel gioco a tema Halloween.`,
