  Kc = `Viene rappresentata sullo sfondo delle sezioni dedicate alla promozione incrociata di questi saldi, come la pagina Sconti ed eventi. Viene utilizzata la stessa immagine per tutte le lingue. L'immagine occupa l'intera sezione da un bordo all'altro e viene ritagliata per adattarsi, quindi tieni lontano dai bordi tutto ciò che è importante, soprattutto da quello superiore e da quello inferiore.`,
