  cl = `Questa pagina dei saldi non mostra il proprio logo. Il logo compare solo su altre pagine di promozione incrociata di questi saldi.`,
  ll = `Capsule del Negozio`,
  ul = `Queste capsule consentono al Negozio di presentare questa pagina di saldi nei luoghi in cui normalmente appaiono i giochi: il banner a scorrimento dei contenuti in evidenza e consigliati, gli hub del Negozio e il carrello. Sono le stesse capsule che un gioco carica sotto la scheda delle risorse grafiche della sua pagina del Negozio, con le stesse dimensioni.`,
  dl = `Puoi caricarle tutte contemporaneamente. Un'immagine viene assegnata automaticamente a una capsula quando le sue dimensioni corrispondono esattamente a quelle della capsula; dovrai assegnare autonomamente tutto il resto, che ti verrà chiesto di ritagliare. Puoi assegnare un nome ai tuoi file d'immagine, in modo che terminino con il nome di una lingua e classificarli così sotto tale lingua (ad es. "capsula_principale_francese.jpg").`,
  fl = `Concentrati sul marchio dei saldi. Assicurati che il logo sia chiaramente leggibile.`,
  pl = `Appare nelle sezioni consigliate e negli spazi dedicati più ristretti all'interno del Negozio.`,
