  Fl = `Permette di cliccare sul logo della pagina dei saldi per portare l'utente in un luogo diverso dal Negozio, ad esempio la pagina iniziale.`,
  Il = `Inserisci solo la parte dell'indirizzo successiva alla pagina principale del Negozio, senza la barra iniziale. Ad esempio, digita category/pins_pegs per collegarti a https://store.steampowered.com/category/pins_pegs`,
  Ll = `Questo indirizzo dev'essere relativo alla pagina principale del Negozio, quindi rimuovi il prefisso https://store.steampowered.com/. Ad esempio, digita category/pins_pegs anziché https://store.steampowered.com/category/pins_pegs`,
