  zu = `Seleziona uno o più file da caricare per importare il testo localizzato per il tuo titolo, sottotitolo, riepilogo e descrizione. Utilizziamo l'estensione del file per determinare se si tratti di un'importazione in formato XML o CSV. Nel caso di file XML, utilizziamo il codice API della lingua alla fine del nome del file, prima dell'estensione, per determinarne la lingua. Inizia esportando un file CSV o XML per accertarti di lavorare con il formato corretto.`,
