  Sd = `L'orario di inizio (%1$s) di questo evento è già passato. Imposta un orario futuro o corrente. Se gli eventi fossero pubblicati dopo il loro inizio effettivo, potrebbero non essere notati dagli utenti che hanno visitato la tua pagina più di recente, dopo l'inizio del tuo evento.`,
