  zd = `La descrizione e/o il nome in inglese dell'evento sono mancanti. L'inglese è la lingua primaria o predefinita di molti utenti di Steam e non includerla significa limitare di molto la visibilità dell'evento.`,
  Bd = `Non è presente alcuna illustrazione. Gli eventi supportano immagini che aiutano a dare un'impronta all'evento e renderlo più interessante per i clienti di Steam. Senza un'immagine, verrà utilizzata automaticamente un'immagine del gioco.`,
  Vd = `Non è presente alcuna immagine. Gli eventi supportano immagini personalizzate che aiutano a dare un'impronta all'evento e renderlo più interessante per i clienti di Steam. Senza un'immagine, verrà utilizzato automaticamente l'avatar del gruppo.`,
  Hd = `La categoria dell'evento è impostata su "altro", il che ne riduce di gran lunga la visibilità. Steam utilizza le categorie dei vari eventi per mostrarli ai clienti. Un evento categorizzato come "altro" verrà considerato di basso impatto e mostrato a un numero inferiore di utenti.`,
  Ud = `I sottotitoli esistono in %1$s lingue su %2$s. Consigliamo che ogni lingua supportata abbia un sottotitolo tradotto.`,
  Wd = `Le immagini tradotte esistono in %1$s lingue su %2$s. È possibile ignorare questo avviso se l'immagine non richiede una traduzione. Per impostazione predefinita, le immagini senza traduzione saranno mostrate in inglese.`,
  Gd = `Il tempo di visibilità per l'evento è stato anticipato e quindi sarà visibile una volta salvato. L'orario di inizio non può essere modificato o nascosto dopo la pubblicazione.`,
