  qd = `L'URL di riferimento del logo della pagina dei saldi non è relativo alla pagina principale del Negozio, quindi cliccando sul logo i clienti verranno reindirizzati a una pagina non funzionante. Dev'essere nel formato category/pins_pegs, non https://store.steampowered.com/category/pins_pegs`,
