  Ph = `Se utilizzi un ciclo di visibilità degli aggiornamenti dopo aver pubblicato questo evento, questo verrà visualizzato nella pagina "Aggiornati di recente" per i giocatori che possiedono o desiderano il tuo gioco.`,
