  $h = `Sulla pagina del Workshop`,
  eg = `Puoi anche pubblicare questo evento/annuncio nel Workshop di Steam per il tuo gioco. Per farlo, passa alla scheda "Opzioni" e seleziona "Pubblica anche sul tuo Workshop". Per impostazione predefinita gli annunci e gli eventi non appaiono nella sezione Workshop.`,
  tg = `Banner della pagina del prodotto dei saldi di Steam`,
  ng = `Banner della pagina del prodotto visibile dal %1$s fino al %2$s`,
  rg = `Puoi fornire nella scheda Saldi un banner dei saldi che collega i giochi in evidenza con la pagina dei saldi tramite la visualizzazione del banner in cima alla pagina del prodotto di Steam. È utile per gli utenti di Steam che scoprono uno sconto specifico su un gioco tramite l'e-mail della Lista dei desideri o esplorando il Negozio, e che finiscono per scoprire l'evento generale dei saldi. Questi banner sono visibili solo dall'inizio alla fine dell'evento o per due settimane, a seconda di quale delle due opzioni si verifica per prima. Gli orari degli eventi sono specificati nella scheda Opzioni.`,
  ig = `Notifica: invia una e-mail ai giocatori che seguono il tuo gioco, il tuo sviluppatore o il tuo editore`,
  ag = `Ciò include tutti i fan di questo gioco associati a pagine di sviluppo, pagine di editori e pagine di franchise.`,
