  pg = `Giocatori che ricevono un messaggio di marketing`,
  mg = `Numero stimato di giocatori che vedranno questo evento nel messaggio di marketing personalizzato del client di Steam. Questo è un popup che appare all'avvio del client di Steam e che mostra le offerte rilevanti di Steam e le informazioni sugli eventi interessanti.`,
