  bg = `Dopo che l'evento è completo e non sono necessarie ulteriori modifiche, invialo per la revisione per poterlo utilizzare in un messaggio di marketing. Puoi pubblicare l'aggiornamento importante appena la revisione è pronta. Sono necessari fino a %1$s giorni lavorativi per la revisione e l'approvazione.`,
