  Dg = `Nota che i nuovi post vengono controllati dal nostro team di moderazione nell'ordine in cui vengono ricevuti. Potrebbe volerci oltre 1 ora prima che notizie o eventi appaiano nella Libreria di Steam. Modificare post esistenti farà sì che il post vada nuovamente nella coda di moderazione.`,
  Og = `Oppure sostituisci il contenuto dell'evento esistente`,
  kg = `Non comune. Consente di organizzare gli aggiornamenti in una specie di evento "bozza" e quindi di sostituire il contenuto di un evento pubblicato esistente con il contenuto di questo evento. Questo evento scomparirà e il relativo contenuto sostituirà l'evento pubblicato mirato. Il tipo di evento e le impostazioni di visibilità dell'evento di destinazione non verranno aggiornati.`,
