  B_ = `Mostra riproduttori a tutto schermo`,
  V_ = `Quando questa opzione è impostata, rimuoverà le colonne sinistra e destra dal riproduttore. Utile solo quando c'è un'unica trasmissione per l'evento e le colonne distraggono dall'esperienza.`,
  H_ = `Abilita modalità riproduttore a tutto schermo`,
  U_ = `Se consentito, viene visualizzato il pulsante Mostra/Nascondi chat. Quando la chat appare, tornerà nella normale modalità riproduttore non a tutto schermo. Quando la chat viene chiusa, tornerà nella modalità riproduttore a tutto schermo.`,
