  tv = `Se abilitato, il banner verrà visualizzato nel Negozio di Steam anziché nelle capsule di gioco. Ciò è utile quando il banner comunica più informazioni applicabili all'evento rispetto a una o più capsule specifiche dell'app. Utile anche quando più giochi trasmettono contemporaneamente e desideri mostrare solo una singola immagine per l'evento.`,
