  sv = `Impossibile caricare le informazioni dell'utente`,
  cv = `Impostazione facoltativa che permette di contrassegnare una trasmissione in modo che abbia una lingua parlata specifica per il pubblico. Utile in caso siano presenti più trasmissioni in lingue diverse per questo evento, in modo da permetterci di scegliere la trasmissione predefinita migliore per l'utente sulla base della sua lingua.`,
  lv = `Priorità`,
