  ty = `Dal vivo`,
  ny = `Si usa quando l'evento in programma è accessibile solo a chi è presente all'evento, che non può essere trasmesso in diretta. Nota: potrebbe non valere la pena includere questo evento nella programmazione, dato che i tuoi fan su Steam non possono partecipare.`,
