  oy = `Questa voce del programma è stata modificata dall'impostazione predefinita. Sei sicuro di volerla eliminare? Questa azione non può essere annullata`,
  sy = `Tracce attuali`,
  cy = `Una traccia lega una serie di eventi correlati con un'immagine di brand comune e uno schema di colori simile. Non è necessario che gli eventi appaiano nella programmazione. Ad esempio, area principale o traccia artistica.`,
  ly = `Nessuna traccia definita.`,
