  my = `Traccia senza contrassegno %1$s`,
  hy = `Aggiungi gli eventi in modo specifico per questa traccia. Sono validi solo se sono stati pubblicati, se iniziano e terminano entro il periodo stabilito e corrispondono alla tipologia di evento permesso per la programmazione.`,
  gy = `Accordi per gli eventi dei saldi`,
  _y = `Prima di poter utilizzare gli strumenti dell'editor dei saldi, dovrai accettare i requisiti seguenti:`,
  vy = `Sono consapevole che la pagina dei saldi deve descrivere chiaramente il gruppo o gli individui responsabili dell'organizzazione dei saldi o dell'evento.`,
  yy = `Sono consapevole di non poter garantire ai partecipanti un certo livello di visibilità su Steam e di non poter richiedere pagamenti per il posizionamento all'interno della pagina.`,
  by = `Sono consapevole che Valve si riserva il diritto di modificare una pagina dei saldi tra cui, a titolo esemplificativo ma non esaustivo, la visibilità dei giochi o le trasmissioni sulla pagina, oppure testo o immagini che descrivono l'evento.`,
  xy = `Sono consapevole che Valve può scegliere gli eventi da promuovere all'interno del Negozio di Steam e che il mio evento potrebbe non essere promosso.`,
  Sy = `Sono consapevole che posso aggiungere alla pagina dei saldi solo i giochi per i quali ho ricevuto l'autorizzazione dallo sviluppatore o dall'editore. Gli sviluppatori di un gioco vedranno che il loro gioco è incluso nei miei saldi non appena lo aggiungerò alla mia pagina qui.`,
  Cy = `Accetto tutte le regole stabilite nella %1$s`,
