  Hy = `Inserisci il nome dell'entità che ha organizzato questo evento. Il link può essere la pagina da autore dell'organizzatore su Steam o può essere un URL esterno. È obbligatorio indicare il nome in inglese ma può essere facoltativamente tradotto in altre lingue.`,
