  gx = `Ogni logo e ogni testo devono essere centrati e all'interno degli 800 pixel medi`,
  _x = `Logo`,
  vx = `Carica i file con la lingua come ultima parte del nome del file per categorizzarli automaticamente come specifici per quella lingua (per esempio, “header_french.jpg”). %1$s per l'elenco delle lingue supportate.`,
  yx = `Traduzione`,
