  xx = `Carica immagini`,
  Sx = `Gestisci 1 immagine`,
  Cx = `Gestisci %1$s immagini`,
  wx = `Aggiungi un'immagine dell'intestazione ricca alla tua pagina dei dettagli per comunicare il tema o l'essenza del tuo aggiornamento o annuncio. Tieni presente che è importante scaricare i modelli (link in cima a questa pagina) per assicurarti che l'immagine dell'intestazione sia progettata in modo appropriato per le diverse circostanze in cui verrà utilizzata.`,
  Tx = `Anteprima della tua pagina dei dettagli:`,
  Ex = `Anteprima della pagina di notifica del tuo evento:`,
  Dx = `Questa immagine apparirà nel pannello laterale, a fianco della tua trasmissione.`,
  Ox = `Gli eventi e gli annunci importanti possono includere un'immagine del banner che viene mostrata nella pagina del tuo Negozio per la durata dell'evento. L'immagine per questo banner è diversa da quella presente altrove nel Negozio. Questi banner devono essere approvati da Valve. Scrivi al tuo contatto a Valve prima di procedere al caricamento.`,
  kx = `Dovresti includere una descrizione breve e accattivante del tuo evento che appaia chiaramente nel tuo banner "sotto i riflettori", in modo che i giocatori possano notare subito gli aspetti più interessanti del tuo evento.`,
  Ax = `Puoi usare tutto lo spazio dell'immagine e includere la descrizione del tuo aggiornamento o evento all'interno della tua immagine.`,
  jx = `Questa è una versione per dispositivi mobili del banner "Sotto i riflettori" e viene usata quando un utente visualizza il banner in uno schermo dalle dimensioni ridotte.`,
  Mx = `Questa immagine apparirà come sfondo della tua pagina dei saldi. Puoi creare questa immagine come un'unica grande immagine o realizzare una casella e impostarla come un pattern che si ripete.`,
  Nx = `I contenuti più importanti dovrebbero essere posizionati nei 940 pixel centrali della tua immagine. L'illustrazione può superare i bordi laterali e inferiori della pagina, se lo desideri. Consigliamo di sfumare l'illustrazione in un colore solido sui lati e sul fondo e poi di impostare lo sfondo sullo stesso colore. L'immagine non può superare i 4 MB.`,
  Px = `Scarica tutti i modelli per le pagine dei saldi (file .psd)`,
  Fx = `L'immagine di sfondo dei saldi è appropriata per il logo della pagina dei saldi indicato qui sotto. Se vengono usati insieme, il logo della tua pagina dei saldi sarà posizionato sopra lo sfondo.`,
  Ix = `Modelli`,
  Lx = `Questa immagine sarà sovrapposta allo sfondo nella parte superiore della tua pagina. Se desideri localizzare le immagini, invia un file .psd al tuo contatto Valve tramite e-mail.`,
  Rx = `Se fornito, questo banner apparirà nella pagina del Negozio per tutti i giochi che partecipano a questo evento di saldi. Questo banner ha la stessa durata dell'evento, fino a un massimo di due settimane. Ricorda che questo banner deve essere approvato da Valve prima di poter essere usato e non può essere animato.`,
  zx = `Questa versione appare solo quando la risoluzione della pagina viene ridotta per il display di un dispositivo mobile.`,
  Bx = `Puoi anche aggiornare la tua immagine distintiva della Libreria con il tuo marchio per gli aggiornamenti, annunci, eventi stagionali o altri tipi di eventi. Visita la scheda "Risorse grafiche" nella pagina del Negozio.`,
  Vx = `Aspetto`,
  Hx = `Dimensioni`,
  Ux = `Utilizzo`,
  Wx = `Necessario`,
  Gx = `Facoltativo`,
  Kx = `Questa immagine di solito contiene illustrazioni e branding che rappresentano il tuo evento ed eventuali messaggi che desideri mettere in evidenza. Steam includerà automaticamente il titolo e l'icona del tuo gioco vicino a questa immagine in alcuni contesti, ma potresti volere includere il logo del tuo gioco anche nell'immagine di copertina, poiché è quella che sarà usata quando l'evento viene condiviso sui social.`,
  qx = `Questa immagine apparirà nella tua pagina del Negozio, nelle liste di eventi e annunci e sulla tua pagina dei dettagli della Libreria. Viene usata per rappresentare il tuo evento quando è condiviso sui social media. È anche usata come collegamento al tuo evento o annuncio e potrebbe venire mostrata accanto ai contenuti di altri giochi, quindi ti consigliamo di renderla chiara e riconoscibile.`,
  Jx = `Questa immagine di solito contiene illustrazioni e marchi che rappresentano il tuo editore, sviluppatore o franchise. Steam includerà automaticamente l'icona del tuo avatar accanto a questa immagine in alcuni contesti.`,
  Yx = `Apparirà all'interno di Steam nelle posizioni in cui viene visualizzata questa pagina da autore e verrà utilizzata per rappresentare l'evento quando è condiviso sui social media. L'immagine dovrebbe essere chiara e riconoscibile.`,
  Xx = `Immagine del banner "Migliore dell'anno" nei grafici di Steam`,
  Zx = `Viene rappresentata nelle sezioni di promozione incrociata di questi saldi, ad esempio nella pagina Sconti ed eventi, al posto del logo della pagina dei saldi. Se questo logo non deve essere localizzato, caricalo una sola volta, in inglese: verrà utilizzato da tutte le lingue.`,
  Qx = `Un logo che viene visualizzato nella parte superiore della tua pagina dei saldi sopra l'immagine di sfondo. Questa immagine deve contenere il logo dell'evento, le date, lo slogan e deve presentare uno sfondo trasparente.`,
