  fS = `Il rettangolo rosso mostrato sull'immagine indica lo spazio all'interno del quale il tuo logo e qualsiasi testo dovrebbero adattarsi. Quella sotto area verrà mostrata in alcuni contesti come ad esempio gli elenchi degli eventi.`,
