  OS = `Modifica i metadati dell'applicazione`,
  kS = `Autorizza a caricare depot, provare le funzionalità di Steamworks, definire pacchetti, achievement e classifiche, pubblicare carte collezionabili e così via. Assegna anche l'accesso e la designazione da amministratori e moderatori per la Comunità di Steam e per tutte le applicazioni nel gruppo.`,
