  HS = `Gestisci le firme`,
  US = `Può gestire le firme digitali per il tuo titolo. In questo modo sarà abilitata la gestione delle impostazioni relative agli Anti-Cheat e alle autorizzazioni dell'SDK per un'applicazione.`,
  WS = `Gestisci i codici prodotto`,
  GS = `Modifica dati di marketing dell'applicazione`,
  KS = `Autorizza la modifica e la pubblicazione di dati della pagina del Negozio come la descrizione del gioco, le immagini rappresentative e i video. Include anche l'accesso a strumenti di marketing come i cicli di visibilità.`,
  qS = `Modifica i dati di localizzazione del Negozio`,
  JS = `Autorizza la modifica di tutti dati della pagina del Negozio che includono uno o più campi localizzabili, come la descrizione del prodotto, e le risorse grafiche. Non autorizza a pubblicare o ad accedere a strumenti di marketing come i cicli di visibilità. Nota: è un sottogruppo della funzionalità "Modificare i dati di marketing dell'applicazione".`,
