  uT = `Articoli non utilizzati - %1$s`,
  dT = `Questa è una lista di tutti gli articoli collegati al saldo e che al momento non si trovano in ALCUNA sezione, né esplicitamente né per via di un filtro. Utile per accertarsi che tutti gli elementi del saldo siano visibili e per esplorare gruppi di articoli non utilizzati.`,
