  mT = `Gli articoli collegati forniscono un insieme di articoli e attributi associati che possono essere aggiunti a uno sconto attraverso dei filtri in grado di selezionare gli articoli che corrispondono a un criterio ben definito. È importante notare che questi articoli non fanno effettivamente parte dei saldi e non sono visibili agli utenti fino a quando non vengono inclusi in una scheda o in una sezione dei saldi tramite un filtro.`,
