  HL = `Come desideri che i contenuti di questa sezione appaiano? Scegli un'opzione preimpostata o configura manualmente.`,
  UL = `<1>Opzioni di layout predefinite</1>: seleziona un'opzione predefinita per configurare rapidamente questa sezione. Puoi sempre utilizzare le impostazioni manuali sottostanti per apportare piccole modifiche o cambiare completamente il layout.`,
