  $L = `Queste opzioni sono disponibili solo quando gli articoli per riga sono impostati su uno.`,
  eR = `Visualizzazione predefinita della capsula`,
  tR = `L'oggetto della capsula predefinita con informazioni aggiuntive come la data di rilascio, le piattaforme, fino a 5 etichette e una breve descrizione del gioco.`,
