  rR = `Mostra la capsula a dimensioni intere, contenente le informazioni che sarebbero mostrate nel bordo e, inoltre, recensioni e azioni dirette per la Lista dei desideri`,
  iR = `Visualizzazione capsula verticale`,
  aR = `Una visualizzazione più alta che utilizza la capsula verticale del Negozio. Contiene tutte le informazioni della capsula intera e aggiunge elementi interattivi come la possibilità di guardare il trailer e passare da uno screenshot all'altro. I bundle non potranno usare questa visualizzazione e verranno mostrati nella capsula intera. I pacchetti useranno la risorse della Libreria dell'applicazione primaria.`,
  oR = `Visualizzazione capsula verticale animata`,
