  uR = `Vetrina solo acquisto`,
  dR = `Vetrina molto semplice per i pacchetti deluxe. Non include alcuna immagine della capsula, solo il nome e i pulsanti per l'acquisto.`,
  fR = `Mostra il pulsante "Opzioni di acquisto"`,
  pR = `Quando questa opzione è selezionata, sostituiremo il pulsante Aggiungi al carrello con un pulsante che mostra tutte le opzioni di acquisto.`,
  mR = `Sezione di rivelamento dinamico`,
  hR = `Una sezione di rivelamento dinamico è utile quando usata insieme alla trasmissione in diretta di un annuncio. Consente all'operatore di aggiungere applicazioni/pacchetti/bundle al Negozio dopo l'avvio dei saldi in modo che appaiano ai client di Steam nella pagina senza che questa debba essere aggiornata. Consigliamo di posizionare questa sezione vicino al riproduttore. Assicurati di aggiungere solo applicazioni visibili, altrimenti alla memoria cache del PC le applicazioni risulteranno sempre non visibili e gli utenti di Steam non le vedranno.`,
  gR = `Nascondi se non ci sono abbastanza articoli`,
  _R = `La sezione sarà nascosta se non ci sono abbastanza articoli da riempire una riga.`,
  vR = `Nascondi eventi duplicati`,
  yR = `Se questa opzione è selezionata, gli eventi in questa sezione che sono già stati visualizzati in una sezione precedente saranno rimossi. Funziona meglio se le sezioni precedenti sono sezioni di eventi curati manualmente o sezioni che mostrano gli eventi contrassegnati recenti di giochi nella Lista dei desideri, nella Libreria o nei consigli dell'utente.`,
  bR = `Viene utilizzata una sezione di rilevamento dinamico in combinazione con la trasmissione in diretta di un annuncio. Si consiglia di collocare questa sezione vicino al riproduttore della trasmissione sulla pagina dei saldi. Controlla periodicamente se sono stati aggiunti nuovi eventi di Steam a questo elenco e mostra gli eventi di Steam senza bisogno che il cliente aggiorni la pagina.`,
  xR = `È consentita solo una sezione di rivelamento dinamico per applicazione/bundle/pacchetto e una per notizie ed eventi`,
