  eH = `Se vengono impostate le risorse facoltative, saranno mostrate all'utente PRIMA di ottenere la medaglia stessa. Ciò è utile quando intendi nascondere certi dettagli della medaglia prima che sia ottenuta. La risorsa dovrebbe essere di 160x160 pixel.`,
