  nY = `Il nome di questa sfaccettatura. Una sfaccettatura è un gruppo di opzioni correlate, ciascuna delle quali è cliccabile dall'utente per filtrare i giochi mostrati in questa sezione. Ad esempio, "Genere".`,
  rY = `Popola automaticamente le sfaccettature e i valori delle sfaccettature sulla base delle categorie delle etichette del Negozio, come "Genere" e "Grafica e visuale". Dopo che i valori sono stati generati automaticamente, puoi modificare manualmente ogni sfaccettatura e i valori delle sfaccettature in base alle necessità.`,
  iY = `Elimina tutti i valori delle sfaccettature che non corrispondono ad alcuno degli elementi di questa sezione.`,
  aY = `Qual è il numero minimo di risultati che desideri per ogni sfaccettatura selezionata? Ciò nasconderà tutti i termini dal menu di sinistra che non raggiungono almeno questo numero di elementi corrispondenti. Questo conteggio viene calcolato dopo l'applicazione di qualsiasi filtro sulla scheda. Generalmente, 5 è un buon numero.`,
  oY = `Mostra questo numero massimo di opzioni in qualsiasi categoria di livello superiore nel menu di sinistra. Ad esempio, non mostra più di questo numero di generi sotto una sfaccettatura chiamata "Genere". Generalmente, 5 è un buon numero.`,
  sY = `Ordina i valori di ogni sfaccettatura in base a questa metrica. L'opzione migliore è solitamente per numero di partite contate.`,
  cY = `All'interno di ogni sfaccettatura, ordina i valori delle sfaccettature in ordine alfabetico del nome.`,
  lY = `All'interno di ogni sfaccettatura, ordina i valori delle sfaccettature in ordine decrescente in base al numero di articoli corrispondenti. Ad esempio, in una sfaccettatura chiamata "Genere", "GDR" apparirà prima di "Strategia" se questa sezione contiene più giochi GDR che giochi di Strategia.`,
  uY = `Non ordina i valori delle sfaccettature, che verranno mostrati nell'ordine definito negli elenchi sottostanti.`,
